CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, amount DECIMAL);
CREATE INDEX idx_customer ON orders (customer_id);
INSERT INTO orders VALUES (1, 501, 120.00);
INSERT INTO orders VALUES (2, 502, 45.00);
INSERT INTO orders VALUES (3, 501, 30.00);
CREATE VIEW customer_totals AS
SELECT customer_id, SUM(amount) AS total_amount, COUNT(*) AS order_count
FROM orders
GROUP BY customer_id;
SELECT * FROM customer_totals ORDER BY customer_id;
